def countMatchingSubarrays(nums, pattern):
    n = len(nums)
    m = len(pattern)
    count = 0

    # Loop over every possible subarray of length m+1 in nums
    for i in range(n - m):
        matches = True
        # For each index in the pattern, check the relationship
        for k in range(m):
            if pattern[k] == 1:
                if nums[i + k + 1] <= nums[i + k]:
                    matches = False
                    break
            elif pattern[k] == 0:
                if nums[i + k + 1] != nums[i + k]:
                    matches = False
                    break
            elif pattern[k] == -1:
                if nums[i + k + 1] >= nums[i + k]:
                    matches = False
                    break
        if matches:
            count += 1
    return count
